    if len(lst) != 2:
        return 'No'

    for string in lst:
        if not all(char in ['(', ')'] for char in string):
            return 'No'

    count = 0
    for char in lst[0] + lst[1]:
        if char == '(':
            count += 1
        else:
            count -= 1
        if count < 0:
            return 'No'

    return 'Yes'

# Test cases
print(match_parens(['()(', ')']))  # Output: Yes
print(match_parens([')', ')']))     # Output: No

